#pragma once

// Stateless pieces of an output session's text publication, shared by the Qwen3.5 and Inkling 2 frontends: the
// incremental UTF-8 decoding of generated bytes and the hold a stop string's possible start keeps back.

#include "infernix/types.h"

#include <cstddef>
#include <string>
#include <string_view>

namespace infernix::models {

inline constexpr std::string_view kUtf8Replacement = "\xef\xbf\xbd";

// Takes the complete code points from `pending` (a malformed sequence becomes U+FFFD, one maximal subpart at a
// time) and leaves an incomplete trailing sequence there for the next bytes.
[[nodiscard]] std::string consume_generated_utf8(std::string& pending);

// The longest proper prefix of `marker` that `text` ends with.
[[nodiscard]] std::size_t longest_suffix_prefix(std::string_view text, std::string_view marker);

// The bytes at the end of `text` that could start one of the policy's stop strings on `channel`.
[[nodiscard]] std::size_t stop_hold_size(std::string_view text, OutputChannel channel, const StopPolicy& policy);

} // namespace infernix::models
